def _round_half_up(numerator, denominator):
    # Exact half-up rounding for nonnegative numerator, positive denominator.
    return (2 * numerator + denominator) // (2 * denominator)


def calculate(lines, tax_percent):
    subtotal = sum(
        line['unit_cents'] * line.get('quantity', 1) for line in lines
    )
    tax = _round_half_up(subtotal * tax_percent, 100)
    return subtotal, tax

